// Verify the Stripe-style signature RFQ Desk puts on every export: t=<unix>,v1=<hmac>.
const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
const secret = $env.OUTBOUND_WEBHOOK_SECRET;
const raw = await this.helpers.getBinaryDataBuffer(0, 'data');

const parts = Object.fromEntries(String(headers['x-rfqdesk-signature'] || '').split(',').map((p) => p.split('=')));
const ts = Number(parts.t);
const expected = crypto.createHmac('sha256', secret).update(`${ts}.`).update(raw).digest('hex');
const fresh = Number.isFinite(ts) && Math.abs(Date.now() / 1000 - ts) < 300;
const valid = Boolean(
  fresh && parts.v1 && parts.v1.length === expected.length &&
  crypto.timingSafeEqual(Buffer.from(parts.v1), Buffer.from(expected))
);

return [{ json: { valid, idempotency_key: headers['x-rfqdesk-idempotency-key'], quote: item.json.body } }];

// Shape the message a sales channel / CRM step would receive.
const { quote, idempotency_key } = $input.first().json;
const total = Number(quote.total).toLocaleString('en-US', { style: 'currency', currency: 'USD' });
const lines = quote.lines.map((l) => `- ${l.quantity} x ${l.sku} (${l.name}) @ $${l.unit_price}`).join('\n');

return [{
  json: {
    channel: '#sales-quotes',
    quote_number: quote.quote_number,
    idempotency_key,
    text: `Quote ${quote.quote_number} approved by ${quote.approved_by}\n` +
      `Customer: ${quote.customer.company || quote.customer.name} <${quote.customer.email}>\n` +
      `Rep: ${quote.assigned_rep} | Total: ${total} | Needed by: ${quote.requested_delivery_date || 'n/a'}\n${lines}`,
  },
}];
